import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:google_fonts/google_fonts.dart';

import '../constants/file_constants.dart';

/// Reusable payment success banner widget.
/// 
/// Displays a payment success card with dynamic amount and status text.
/// Uses the existing thankyouscreenbanner.png as background or fallback.
/// 
/// Figma reference dimensions:
/// - Width: 392px
/// - Height: 450px
/// - Border radius: 12px
class PaymentSuccessBanner extends StatelessWidget {
  const PaymentSuccessBanner({
    super.key,
    required this.amount,
    required this.statusText,
    this.backgroundImage,
  });

  /// The payment amount to display (e.g., "₹500")
  final String amount;

  /// The payment status or message text (e.g., "Payment Successful")
  final String statusText;

  /// Optional custom background image. If null, uses the default banner.
  final String? backgroundImage;

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final screenWidth = mq.size.width;
    
    // Responsive banner width: clamp between 320px and 392px
    final bannerWidth = (screenWidth - 48.w).clamp(320.w, 392.w);
    // Maintain aspect ratio (392:450)
    final bannerHeight = bannerWidth * (450 / 392);

    return SizedBox(
      width: bannerWidth,
      height: bannerHeight,
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          // Background image
          ClipRRect(
            borderRadius: BorderRadius.circular(12.r),
            child: SizedBox(
              width: bannerWidth,
              height: bannerHeight,
              child: (backgroundImage?.trim().isNotEmpty == true)
                  ? Image.asset(
                      backgroundImage!,
                      width: bannerWidth,
                      height: bannerHeight,
                      fit: BoxFit.cover,
                    )
                  : _buildDefaultBanner(bannerWidth, bannerHeight),
            ),
          ),
          // AD badge at top-right corner
          Positioned(
            top: 20.h,
            right: 0,
            child: _buildAdBadge(),
          ),
          // Amount badge positioned on the banner using SVG - moved up
          Positioned(
            top: bannerHeight * 0.25,
            left: 0,
            right: 0,
            child: Center(
              child: _buildAmountBadge(),
            ),
          ),
          // Status text positioned below amount
          Positioned(
            top: bannerHeight * 0.52,
            left: 0,
            right: 0,
            child: Padding(
              padding: EdgeInsets.symmetric(horizontal: 24.w),
              child: Text(
                statusText,
                textAlign: TextAlign.center,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: GoogleFonts.plusJakartaSans(
                  color: Colors.white,
                  fontWeight: FontWeight.w600,
                  fontSize: 16.sp,
                  height: 1.3,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  /// Default banner using the existing thankyouscreenbanner.png
  Widget _buildDefaultBanner(double width, double height) {
    return Image.asset(
      FileConstants.thankYouScreenBanner,
      width: width,
      height: height,
      fit: BoxFit.cover,
    );
  }

  /// Amount badge with dynamic amount using provided SVG
  Widget _buildAmountBadge() {
    return SizedBox(
      width: 106.w,
      height: 34.h,
      child: Stack(
        children: [
          // SVG background
          SvgPicture.string(
            _amountBadgeSvg,
            width: 106.w,
            height: 34.h,
            fit: BoxFit.fill,
          ),
          // Amount text centered
          Center(
            child: Text(
              amount,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: GoogleFonts.plusJakartaSans(
                color: Colors.white,
                fontWeight: FontWeight.w600,
                fontSize: 14.sp,
                height: 1,
              ),
            ),
          ),
        ],
      ),
    );
  }

